INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-baptised-duel-escort', 'arc', 10, 'Baptised Duel Escort', '세례 결투 호위대', 'commander', 'champion', 3, 'House Guard Yard', '가문 호위 마당', 1000, 250, 4, 'implants', 8, 118, 52, 36, 50, 45, NULL, NULL, NULL, 36, 74, '["baptised","plate-biter","thin-clad"]', '["government-conscript-spears","free-city-guard-share-pole-crews","government-aid-post-litter-bearers"]', 'Machine arms with fighting blades and plate fitted over the joints. They stand beside a champion of the house in a duel; the field mechanic who fitted the arms comes with them.', '싸움 날을 단 기계 팔과 이음매를 덮는 판을 갖춘다. 곁집의 투사가 결투할 때 그 곁에 선다. 팔을 맞춘 야전 정비공이 함께 따른다.', 'Two layers: a short coat with the shoulders and knees opened, and sleeves of insulation laced tight on the parts. A red near-house armband; the part count is stitched on the right collar and painted on the helmet.', '두 겹이다. 어깨와 무릎을 튼 짧은 외투에 부위마다 단열 토시를 바짝 끼워 끈으로 여민다. 붉은 곁집 띠를 두르고, 부위 수를 오른쪽 깃에 땀으로 박고 철모에 칠한다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-near-house-heads-guard', 'arc', 20, 'Near House Head''s Guard', '곁집장 호위대', 'commander', 'command', 4, 'Near House Seat Hall', '곁집 본청', 1800, 450, 4, 'implants', 10, 126, 55, 46, 55, 70, NULL, NULL, NULL, 34, 86, '["baptised","roll-call","thin-clad","last-to-leave"]', '["government-checkpoint-shield-line","free-city-contract-shield-company","free-city-field-repair-crews"]', 'Baptised fighters of the house''s own blood with machine arms, short blades and plate. They guard the Near House head, or the guard captain the head chose to command the house''s army.', '곁집의 피붙이인 세례 전투원으로, 기계 팔과 짧은 날, 판을 갖춘다. 곁집장이나 곁집장이 고른 호위장, 곧 곁집 군대의 지휘관을 지킨다.', 'Two layers: a fitted dark coat with repair gaps at every part and a fur collar. A red armband with the house''s pattern; the house mark on the left collar, the part count on the right.', '두 겹이다. 부위마다 정비 틈을 낸 몸에 맞춘 짙은 외투에 털 깃을 단다. 곁집 무늬가 든 붉은 띠를 두르고, 왼쪽 깃에 곁집 무늬, 오른쪽 깃에 부위 수 땀을 놓는다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-hierophant-house-guard', 'arc', 30, 'Hierophant''s House Guard', '교주의 집 호위대', 'commander', 'command', 5, 'Hierophant''s Guard Hall', '교주 호위청', 2900, 725, 1, 'implants', 14, 135, 62, 56, 58, 85, NULL, NULL, NULL, 36, 96, '["baptised","thin-clad","iron-dread","last-to-leave"]', '["government-guard-hall-shield-line","free-city-heads-own-watch","government-aid-post-net-teams"]', 'Fighters sent by all four Near Houses, bound to none of them and following the Hierophant''s word alone. Every one carries machine arms and legs and is first in the repair order.', '네 곁집이 저마다 보낸 전투원으로, 어느 곁집에도 매이지 않고 교주의 말만 따른다. 모두 기계 팔과 다리를 달았고, 정비 차례가 가장 앞선다.', 'One layer of thin fitted wool with no overcoat, repair gaps at every part. A plain red armband with no house pattern, and a long row of part stitches on the right collar.', '겉옷 없이 몸에 붙인 얇은 모직 한 겹이고, 부위마다 정비 틈을 냈다. 곁집 무늬가 없는 붉은 띠를 두르고, 오른쪽 깃에 부위 수 땀이 길게 박혀 있다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-house-levy-hooks', 'arc', 40, 'House Levy Hooks', '가문 징집 갈고리병', 'infantry', 'line', 1, 'House Muster Hall', '가문 집결소', 200, 42, NULL, NULL, 50, 72, 24, 26, 26, 12, NULL, NULL, NULL, 34, 48, '["house-bound","charge-breaker"]', '["free-city-rail-trolley-raiders","free-city-flywheel-trolley-shock-crews","government-bridge-end-sled-patrols"]', 'Hook poles and short spears, gathered from each household of the house''s district by headcount. Most are unbaptised; the house feeds and clothes them.', '갈고리 장대와 짧은 창을 든다. 곁집이 제 구의 집안마다 사람 수를 정해 모은 사람들로, 대개 미세례자다. 곁집이 먹이고 입힌다.', 'Four layers, the thickest coats in the Arc because the unbaptised take the exit watches: wool and felt layers with the repair gaps sewn shut, felt boots and a fur cap. A red armband with the house pattern.', '네 겹이고, 미세례자가 출입구 당번을 맡으므로 아크에서 가장 두꺼운 외투를 입는다. 정비 틈을 꿰매 둔 모직·펠트 겹옷과 펠트 장화, 털모자다. 곁집 무늬가 든 붉은 띠를 두른다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-house-levy-cleavers', 'arc', 50, 'House Levy Cleavers', '가문 징집 도끼병', 'infantry', 'shock', 1, 'House Muster Hall', '가문 집결소', 230, 48, NULL, NULL, 40, 69, 28, 16, 34, 8, NULL, NULL, NULL, 36, 46, '["house-bound"]', '["government-reserve-riflemen","free-city-station-air-rifle-guards","government-conscript-air-rifles","free-city-rail-spike-throwers"]', 'Cleavers and hatchets from the shelters'' kitchens and wood stores. They rush shooters in the close tunnels, where a few steps decide the fight.', '대피소 부엌과 나무 창고에서 나온 큰 칼과 손도끼를 든다. 몇 걸음이 싸움을 가르는 좁은 터널에서 사수에게 달려든다.', 'Four layers: wool and felt coats with sewn-shut repair gaps, padded trousers and felt boots. A red armband with the house pattern; no part stitches.', '네 겹이다. 정비 틈을 꿰맨 모직·펠트 외투와 솜 바지, 펠트 장화다. 곁집 무늬가 든 붉은 띠를 두르고, 부위 수 땀은 없다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-house-shield-bearers', 'arc', 60, 'House Shield Bearers', '가문 방패병', 'infantry', 'line', 2, 'House Muster Hall', '가문 집결소', 480, 100, NULL, NULL, 40, 80, 26, 44, 22, 45, NULL, NULL, NULL, 30, 60, '["house-bound","shield-line"]', '["government-regular-riflemen","free-city-brass-counting-riflemen","government-reserve-riflemen"]', 'Tall shields from shelter blast doors and short spears. They hold the tunnel mouths so the baptised can strike from behind them.', '대피소 방폭문으로 만든 큰 방패와 짧은 창을 든다. 세례 전투원이 그 뒤에서 칠 수 있도록 터널 입구를 막는다.', 'Three layers: a quilted coat with a repair gap at each part a bearer has, felt boots and a helmet. A red armband with the house pattern.', '세 겹이다. 가진 부위마다 정비 틈을 낸 누빔 외투와 펠트 장화, 철모다. 곁집 무늬가 든 붉은 띠를 두른다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-house-exit-breakers', 'arc', 70, 'House Exit Breakers', '가문 출입구 돌파병', 'infantry', 'breacher', 2, 'House Muster Hall', '가문 집결소', 560, 118, NULL, NULL, 24, 82, 30, 22, 48, 28, NULL, NULL, NULL, 33, 58, '["house-bound","breach-charge"]', '["free-city-crew-net-teams","government-aid-post-net-teams","free-city-field-repair-crews"]', 'Sledges, pry bars and hatch hooks for shaft covers and barricades. They open the door; the baptised go through it.', '굴 덮개와 방벽을 여는 큰 망치와 지렛대, 덮개 갈고리를 든다. 문은 이들이 열고, 그 문으로는 세례 전투원이 들어간다.', 'Three layers: a short quilted coat, leather aprons and thick gloves. A red armband with the house pattern and a white band on the helmet.', '세 겹이다. 짧은 누빔 외투와 가죽 앞치마, 두꺼운 장갑이다. 곁집 무늬가 든 붉은 띠를 두르고 철모에 흰 띠를 둘렀다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-baptised-strong-arm-squad', 'arc', 80, 'Baptised Strong-Arm Squad', '세례 팔힘대', 'infantry', 'shock', 3, 'Baptism Training Hall', '세례 수련장', 1100, 275, 4, 'implants', 20, 118, 50, 32, 56, 52, NULL, NULL, NULL, 34, 74, '["baptised","plate-biter","thin-clad","iron-dread"]', '["government-regular-riflemen","free-city-passage-marksmen","government-rim-ski-scouts"]', 'Machine arms that grip and swing heavy hammers, and plates over the joints. Baptised fighters with at least two parts, twenty or older, picked by a repair chief who has looked at each body.', '무거운 망치를 쥐고 휘두르는 기계 팔과 이음매를 덮는 판을 갖춘다. 부위 둘 이상, 스무 살 이상인 세례 전투원으로, 정비장이 몸을 하나하나 보고 골랐다.', 'Two layers: a short coat with the shoulders opened, and insulation sleeves laced on the arms. A red armband; the part count on the collar and helmet.', '두 겹이다. 어깨를 튼 짧은 외투에 팔마다 단열 토시를 끈으로 여민다. 붉은 띠를 두르고, 깃과 철모에 부위 수를 적는다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-baptised-plate-breakers', 'arc', 90, 'Baptised Plate-Breakers', '세례 쇠뚫이대', 'infantry', 'anti-armour', 3, 'Baptism Training Hall', '세례 수련장', 1150, 290, 4, 'implants', 20, 118, 40, 30, 60, 50, NULL, NULL, NULL, 33, 72, '["baptised","plate-biter","machine-hunter","thin-clad"]', '["free-city-rail-trolley-raiders","free-city-flywheel-trolley-shock-crews","government-bridge-end-sled-patrols"]', 'Machine hands that drive spikes through plate and tear open hatches. With no artillery and no drones, these are how the Arc meets armour.', '판에 쇠못을 박고 덮개를 뜯는 기계 손을 갖춘다. 포도 드론도 없는 아크가 장갑을 맞는 방법이 이들이다.', 'Two layers: a short coat with the sleeves cut off at the elbow, insulation sleeves on the hands. A red armband; the part count on the collar and helmet.', '두 겹이다. 소매를 팔꿈치에서 잘라 낸 짧은 외투에 손마다 단열 토시를 낀다. 붉은 띠를 두르고, 깃과 철모에 부위 수를 적는다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-baptised-near-house-guard', 'arc', 100, 'Baptised Near House Guard', '세례 곁집 호위병', 'infantry', 'line', 4, 'Baptism Guard Hall', '세례 호위청', 1700, 430, 4, 'implants', 24, 128, 54, 52, 52, 80, NULL, NULL, NULL, 33, 86, '["baptised","house-bound","thin-clad","last-to-leave"]', '["government-watchtower-marksmen","free-city-brass-counting-riflemen","government-heavy-mortar-battery"]', 'Plate fitted over machine limbs, short blades and riveted shields. The line of each house''s army, holding a station''s tunnel mouths without giving a step.', '기계 팔다리 위에 맞춘 판과 짧은 날, 리벳 박은 방패를 갖춘다. 곁집 군대의 전열로, 역의 터널 입구를 한 걸음도 내주지 않고 막는다.', 'Two layers: a fitted dark coat with repair gaps and a short jacket under it. A red armband with the house pattern; long rows of part stitches.', '두 겹이다. 정비 틈을 낸 몸에 맞춘 짙은 외투 아래 짧은 웃옷을 입는다. 곁집 무늬가 든 붉은 띠를 두르고 부위 수 땀이 길다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-four-part-fighters', 'arc', 110, 'Four-Part Fighters', '네 부위 전투원', 'infantry', 'shock', 4, 'Baptism Guard Hall', '세례 호위청', 1900, 475, 2, 'implants', 20, 132, 56, 56, 58, 90, NULL, NULL, NULL, 36, 88, '["baptised","thin-clad","iron-dread","plate-biter"]', '["government-light-mortar-crews","free-city-bench-mortar-crews","free-city-rail-trolley-raiders"]', 'Fighters with four parts or more: machine arms and legs, plate over spine and trunk. They are the strongest the Arc fields and the first to fail when parts run out.', '부위가 넷 이상인 전투원이다. 기계 팔과 다리, 등뼈와 몸통을 덮는 판을 갖췄다. 아크가 내는 가장 강한 분대이고, 부품이 끊기면 가장 먼저 무너진다.', 'One to two layers: a short coat cut open at shoulders and knees and almost nothing else. A red armband and the part count painted large on the helmet.', '한두 겹이다. 어깨와 무릎을 튼 짧은 외투뿐이다. 붉은 띠를 두르고 철모에 부위 수를 크게 칠했다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-house-levy-rifles', 'arc', 120, 'House Levy Rifles', '가문 징집 소총반', 'missile', 'rifle', 1, 'House Muster Hall', '가문 집결소', 260, 55, NULL, 'ammo', 24, 69, 14, 14, 18, 5, 22, 145, 10, 33, 46, '["house-bound"]', '["government-conscript-pick-squads","free-city-digging-bench-axe-crews"]', 'Rifles from the Gangnam shelters'' old stores, about eight hundred in the whole Arc, with ten rounds each. The Arc spends its stock on bodies, not on rounds.', '강남 대피소 옛 창고에서 나온 소총으로, 아크 전체에 약 800정뿐이다. 한 사람에 열 발씩 받는다. 아크는 탄보다 몸에 비축을 쓴다.', 'Four layers for the ground and the exit shafts: wool and felt coats, over-trousers, felt boots and a fur cap. A red armband with the house pattern.', '지상과 출입구 굴에서 쏘므로 네 겹이다. 모직·펠트 외투와 덧바지, 펠트 장화, 털모자다. 곁집 무늬가 든 붉은 띠를 두른다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-house-crossbow-skirmishers', 'arc', 130, 'House Crossbow Skirmishers', '가문 석궁 산개병', 'missile', 'skirmish', 2, 'House Muster Hall', '가문 집결소', 480, 100, NULL, NULL, 24, 72, 16, 18, 20, 15, 28, 120, 14, 36, 58, '["house-bound","muscle-powered","scout-deploy"]', '["government-conscript-spears","free-city-guard-share-pole-crews","government-reserve-club-lines","government-pole-charge-hunters"]', 'Crossbows with steel limbs cut from old springs, and bolts that are picked up again. No powder means no smoke in the stations.', '옛 용수철을 잘라 만든 쇠 활대의 석궁과 다시 주워 쓰는 화살을 든다. 화약이 없으니 역 안에 연기가 남지 않는다.', 'Three layers: a quilted coat, padded trousers and soft boots. A red armband with the house pattern; a bolt bag on the thigh.', '세 겹이다. 누빔 외투와 솜 바지, 무른 장화다. 곁집 무늬가 든 붉은 띠를 두르고 넓적다리에 화살 자루를 찬다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-baptised-eye-marksmen', 'arc', 140, 'Baptised Eye Marksmen', '세례 눈 저격조', 'missile', 'marksman', 3, 'House Guard Yard', '가문 호위 마당', 1000, 250, 3, 'implants,ammo', 12, 90, 18, 20, 22, 25, 52, 190, 10, 34, 72, '["baptised","thin-clad","quiet-step"]', '["government-district-command-escort","free-city-contract-commanders-guard","government-assembly-members-sworn-retinue"]', 'Machine eyes that see in the dark tunnels, and old rifles fired only at a known face. Few rounds, so few shots; this is as far as Arc shooting goes.', '어두운 터널에서도 보는 기계 눈과, 알아본 얼굴에만 쏘는 옛 소총을 갖춘다. 탄이 적으니 쏘는 일도 적다. 아크의 사격은 여기서 멈춘다.', 'Two layers: a short dark coat and a hood opened at the eyes. A red armband; the part count stitched on the collar.', '두 겹이다. 짧은 짙은 외투에 눈 자리를 튼 두건을 쓴다. 붉은 띠를 두르고, 깃에 부위 수 땀을 놓았다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-house-ski-scouts', 'arc', 150, 'House Ski Scouts', '가문 스키 정찰병', 'fast', 'recon', 1, 'House Muster Hall', '가문 집결소', 220, 46, NULL, NULL, 12, 90, 18, 20, 20, 8, NULL, NULL, NULL, 64, 48, '["house-bound","frost-hardened","scout-deploy","quiet-step"]', '["free-city-fibre-scout-drones","government-conscript-air-rifles","free-city-crew-net-teams"]', 'Skis, short spears and a whistle. They watch the bridge south ends and the Cheonggyesan rim from the ground, where the Arc flies no drones.', '스키와 짧은 창, 호루라기를 갖춘다. 아크가 드론을 띄우지 않는 지상에서 다리 남쪽 끝과 청계산 쪽 테두리를 지켜본다.', 'Six layers: wool and felt coats, over-trousers, a white over-suit, felt boots, a fur hood and a face cover. A red armband sewn under the white.', '여섯 겹이다. 모직·펠트 외투와 덧바지, 흰 덧옷, 펠트 장화, 털 두건, 얼굴 가리개다. 붉은 띠는 흰 덧옷 안쪽에 꿰맸다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-house-sled-raiders', 'arc', 160, 'House Sled Raiders', '가문 썰매 습격대', 'fast', 'raider', 2, 'House Muster Hall', '가문 집결소', 540, 114, NULL, NULL, 14, 118, 32, 22, 32, 20, NULL, NULL, NULL, 70, 60, '["house-bound","frost-hardened","quiet-step"]', '["free-city-bench-mortar-crews","government-light-mortar-crews","free-city-wire-guided-rail-strikers","free-city-jamming-teams"]', 'Sleds pulled by teams of four, carrying hatchets and nets. They strike at mortar posts and drone operators across the land border and come back before nightfall.', '넷이 끄는 썰매에 손도끼와 그물을 싣는다. 땅 경계 너머의 박격포 자리와 드론 조종수를 치고 해 지기 전에 돌아온다.', 'Six layers: wool and felt coats, over-trousers, a windproof outer coat, felt boots, a fur hood and a face cover. A red armband with the house pattern.', '여섯 겹이다. 모직·펠트 외투와 덧바지, 바람막이 겉옷, 펠트 장화, 털 두건, 얼굴 가리개다. 곁집 무늬가 든 붉은 띠를 두른다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-baptised-leg-runners', 'arc', 170, 'Baptised Leg Runners', '세례 다리 돌격대', 'fast', 'shock', 3, 'Baptism Training Hall', '세례 수련장', 1050, 262, 4, 'implants', 10, 150, 44, 30, 46, 38, NULL, NULL, NULL, 80, 74, '["baptised","thin-clad","tunnel-fighter"]', '["government-watchtower-marksmen","free-city-passage-marksmen","free-city-relay-strike-flight"]', 'Machine legs that carry a fighter down a tunnel faster than a trolley, and short blades. Their batteries are the first thing the field mechanic checks.', '터널을 수레보다 빨리 달리게 하는 기계 다리와 짧은 날을 갖춘다. 야전 정비공이 가장 먼저 살피는 것이 이들의 전지다.', 'Two layers: a short coat with the trouser legs opened at the knee and insulation sleeves on the legs. A red armband; the part count on the helmet.', '두 겹이다. 짧은 외투에 무릎에서 튼 바지를 입고 다리마다 단열 토시를 낀다. 붉은 띠를 두르고 철모에 부위 수를 적는다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-revived-armoured-locomotive', 'arc', 180, 'Revived Armoured Locomotive', '되살린 장갑 기관차', 'war-machine', 'armour', 5, 'Old Machine Shed', '옛 기계 차고', 3000, 750, 1, 'fuel,parts', 1, 8800, 50, 36, 340, 125, NULL, NULL, NULL, 30, 100, '["irreplaceable","iron-dread","rail-borne"]', '["government-guard-hall-shield-line","free-city-heads-own-watch","government-district-command-escort"]', 'The one battery maintenance locomotive at the old Godeok depot, plated and given a ram, with parts salvaged from the Suseo depot stores. It cannot be built again, and it moves only on a bought power block.', '고덕 옛 차량기지의 하나뿐인 축전지 정비 기관차에 판과 들이받는 판을 달았고, 부품은 수서 기지 창고에서 건진다. 다시 만들 수 없고, 사 온 동력 덩이가 있어야 움직인다.', 'Riveted plate painted dull red with the four house patterns in a row along the side. The crew wears mechanics'' aprons over quilted shirts.', '리벳 박은 판을 흐린 붉은색으로 칠하고 옆면에 네 곁집 무늬를 나란히 그렸다. 조원은 누빈 셔츠 위에 정비공 앞치마를 두른다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-net-throwing-crews', 'arc', 190, 'Net-Throwing Crews', '그물 던지기조', 'support', 'countermeasure', 1, 'Repair Corps Room', '정비대 작업방', 210, 44, NULL, NULL, 12, 70, 14, 16, 18, 8, NULL, NULL, NULL, 34, 50, '["net-casting","house-bound"]', '["free-city-bench-drop-drones","free-city-fibre-scout-drones","government-capital-defence-strike-drones","free-city-relay-strike-flight"]', 'Weighted throwing nets and poles. The Arc answers drones with nets, because it has none of its own to send.', '추를 단 던지는 그물과 장대를 든다. 아크는 띄울 드론이 없으므로 드론에 그물로 맞선다.', 'Four layers: wool and felt coats, padded trousers, felt boots and a fur cap. A red armband with the house pattern.', '네 겹이다. 모직·펠트 외투와 솜 바지, 펠트 장화, 털모자다. 곁집 무늬가 든 붉은 띠를 두른다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-shelter-aid-crews', 'arc', 200, 'Shelter Aid Crews', '대피소 구호조', 'support', 'medic', 2, 'Repair Corps Room', '정비대 작업방', 560, 118, NULL, 'medicine', 12, 72, 12, 16, 18, 6, NULL, NULL, NULL, 34, 58, '["house-bound","field-dressing"]', '["government-capital-defence-scout-drones"]', 'Bandages, a little antibiotic grown from mould in the clean rooms, and a net folded on the litter. A wound around a part is the thing they fear most.', '붕대와 깨끗한 방에서 곰팡이로 기른 항생제 조금, 들것에 접어 둔 그물을 든다. 가장 두려워하는 것은 부위 둘레의 상처다.', 'Three layers: a quilted coat, an apron and felt boots. A red armband with the house pattern and a white band on the sleeve.', '세 겹이다. 누빔 외투와 앞치마, 펠트 장화다. 곁집 무늬가 든 붉은 띠를 두르고 소매에 흰 띠를 맨다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('arc-field-mechanics', 'arc', 210, 'Field Mechanics', '야전 정비공조', 'support', 'engineer', 3, 'Body Repair Hall', '몸 정비청', 980, 245, 5, 'implants', 8, 100, 16, 22, 24, 30, NULL, NULL, NULL, 32, 72, '["baptised","field-repair","field-dressing"]', '["free-city-armoured-battery-trolley","government-armoured-carrier-section"]', 'Tool rolls, spare joints and charged cells for the fighters'' parts. Every Arc army takes field mechanics along; an army that has lost them all turns home.', '공구 두루마리와 예비 이음 부품, 전투원의 부위에 넣을 채운 전지를 든다. 아크 군대마다 야전 정비공이 따르고, 정비공을 모두 잃은 군대는 본역으로 돌아선다.', 'Three layers: a heavy apron over a quilted shirt with the sleeves tied back, burn marks on the apron. A red armband; three or more part stitches on the collar.', '세 겹이다. 누빈 셔츠 위에 덴 자국이 있는 두꺼운 앞치마를 두르고 소매를 묶었다. 붉은 띠를 두르고, 깃에 부위 수 땀이 셋 이상 있다.', NULL);
